function calculateDryerCost() {
  const freq = parseFloat(document.getElementById('dryFrequency').value) || 0;
  const rate = parseFloat(document.getElementById('electricityRate').value) || 0;
  const bathHours = parseFloat(document.getElementById('bathDryerHours').value) || 0;
  const dehumHours = parseFloat(document.getElementById('dehumidifierHours').value) || 0;

  const annualRuns = freq * 52;

  // 浴室乾燥機: 一般的な電気ヒーター式 1250W (1.25kW)
  const bathKwhPerRun = 1.25 * bathHours;
  const bathCostPerRun = bathKwhPerRun * rate;
  const bathCostAnnual = bathCostPerRun * annualRuns;

  // 衣類乾燥除湿機: 省エネ/ハイブリッド平均 300W (0.30kW)
  const dehumKwhPerRun = 0.30 * dehumHours;
  const dehumCostPerRun = dehumKwhPerRun * rate;
  const dehumCostAnnual = dehumCostPerRun * annualRuns;

  // ドラム式洗濯乾燥機: ヒートポンプ式標準乾燥 1回あたり約0.85kWh
  const drumKwhPerRun = 0.85;
  const drumCostPerRun = drumKwhPerRun * rate;
  const drumCostAnnual = drumCostPerRun * annualRuns;

  const savingsVsDehum = bathCostAnnual - dehumCostAnnual;
  const savingsVsDrum = bathCostAnnual - drumCostAnnual;

  const container = document.getElementById('calcResult');
  if (!container) return;

  container.innerHTML = `
    <div class="result-headline">
      結論：除湿機なら浴室乾燥機より年間<strong>約${Math.round(savingsVsDehum).toLocaleString()}円</strong>、ドラム式なら<strong>約${Math.round(savingsVsDrum).toLocaleString()}円</strong>おトクになります！
    </div>
    <div class="metrics-row">
      <div class="metric-card">
        <span>浴室乾燥機 (電気)</span>
        <strong>${Math.round(bathCostPerRun)}円 /回</strong>
        <small>年間: 約${Math.round(bathCostAnnual).toLocaleString()}円</small>
      </div>
      <div class="metric-card">
        <span>衣類乾燥除湿機</span>
        <strong>${Math.round(dehumCostPerRun)}円 /回</strong>
        <small>年間: 約${Math.round(dehumCostAnnual).toLocaleString()}円</small>
      </div>
      <div class="metric-card">
        <span>ドラム式(ヒートポンプ)</span>
        <strong>${Math.round(drumCostPerRun)}円 /回</strong>
        <small>年間: 約${Math.round(drumCostAnnual).toLocaleString()}円</small>
      </div>
    </div>
  `;
}
document.addEventListener('DOMContentLoaded', calculateDryerCost);
